import numpy as np
one=np.ones_like(eps)
def score(cols):
    A=np.column_stack(cols); c,*_=np.linalg.lstsq(A,sigma,rcond=None); rr=sigma-A@c
    return np.sum(rr**2)/np.sum((sigma-sigma.mean())**2),c
fams={'bose':lambda th: 1/(np.exp(th/T)-1),'expneg':lambda th: np.exp(-th/T),'expT':lambda th: np.exp(-th*T),'coth':lambda th: 1/np.tanh(th/T),'logth':lambda th: np.log(T+th),'invth':lambda th: 1/(T+th),'sqrtth':lambda th: np.sqrt(T+th),'bose2':lambda th: T/(np.exp(th/T)-1)}
for fn,f in fams.items():
    best=None
    for th in np.arange(0.05,4.0,0.02):
        with np.errstate(all='ignore'):
            s,c=score([one,eps**1.5,f(th)])
        if np.isfinite(s) and (best is None or s<best[0]): best=(s,th,c)
    s2,c2=score([one,eps**1.5,f(best[1]),T])
    s3,c3=score([one,eps**1.5,f(best[1]),np.sqrt(T)])
    print(fn, best[0], round(best[1],3), np.round(best[2],4), '+T',s2,'+sqrtT',s3)
